import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"旧配置转换器下线清单","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/legacy-converter-retirement.md","filePath":"modules/corelib/legacy-converter-retirement.md","lastUpdated":0}`),a={name:`modules/corelib/legacy-converter-retirement.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="旧配置转换器下线清单" tabindex="-1">旧配置转换器下线清单 <a class="header-anchor" href="#旧配置转换器下线清单" aria-label="Permalink to “旧配置转换器下线清单”">​</a></h1><p><code>convert-legacy</code> 是一次性迁移设施，不是插件功能。本页记录它的<strong>下线契约</strong>：等所有服务器都迁移完成后，照这份清单删除即可，不必重新调查调用点。</p><p>判定位收口本身的说明在<a href="./item-matcher.html">物品匹配器</a>，本页只讲「怎么把转换器整包删掉」。</p><h2 id="为什么单独记一页" tabindex="-1">为什么单独记一页 <a class="header-anchor" href="#为什么单独记一页" aria-label="Permalink to “为什么单独记一页”">​</a></h2><p>转换器分布在 6 个包里（CoreLib 共享引擎 + 5 个模块各自的目标定义），彼此有删除顺序约束。删错顺序会让其余模块的转换器编译失败，而这个依赖关系从代码里看不出来——<code>LegacyMessageSink</code> 还被两个非迁移用途的类实现着。</p><h2 id="删除顺序" tabindex="-1">删除顺序 <a class="header-anchor" href="#删除顺序" aria-label="Permalink to “删除顺序”">​</a></h2><p>CoreLib 的 <code>corelib.legacy</code> 是共享引擎，<strong>被全部 5 个模块依赖</strong>。单独删它会让每个模块的转换器编译失败，所以它必须与模块级 <code>legacy</code> 包在同一次改动里下线，不能提前。</p><h2 id="整包下线清单" tabindex="-1">整包下线清单 <a class="header-anchor" href="#整包下线清单" aria-label="Permalink to “整包下线清单”">​</a></h2><p>一次改动内删除以下全部内容：</p><ol><li><code>EmakiCoreLib</code> 的 <code>corelib.legacy</code> 包；</li><li>5 个模块各自的 <code>legacy</code> 包（Cooking / Forge / Gem / Level / Strengthen）；</li><li>每个模块命令路由里那一行 <code>case &quot;convert-legacy&quot; -&gt; ...</code>，以及 tab 补全列表里的 <code>&quot;convert-legacy&quot;</code> 字符串；</li><li>每个模块双语语言文件中的 <code>command.convert_legacy.*</code> 键；Gem 与 Strengthen 另有 <code>command.help.desc.convert_legacy</code>；</li><li>每个模块加载期的 <code>reportLegacyItemSources()</code> 调用（Strengthen 无此调用）；</li><li><code>AbstractMessageService</code> 与 <code>LevelMessageService</code> 的 <code>implements LegacyMessageSink</code> 子句。</li></ol><p>第 6 项容易漏：<code>LegacyMessageSink</code> 是共享引擎里唯一有非迁移用途消费方的成员，删包时这两个 <code>implements</code> 会变成悬空引用。</p><h2 id="各模块落位" tabindex="-1">各模块落位 <a class="header-anchor" href="#各模块落位" aria-label="Permalink to “各模块落位”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>迁移目标</th><th>命令入口</th><th>删包后需要改的其他位置</th></tr></thead><tbody><tr><td>CoreLib</td><td>共享引擎，无自己的目标</td><td>无</td><td><code>AbstractMessageService</code>、<code>LevelMessageService</code> 的 <code>implements</code></td></tr><tr><td>Cooking</td><td><code>config.yml</code> 与 <code>recipes/</code> 中的旧扁平 matcher 键迁移到嵌套 <code>item_sources</code> + <code>matcher</code>；发酵桶 <code>inputs[]</code> 保留旧键以便兼容状态身份空间</td><td><code>/emakicooking convert-legacy</code></td><td><code>CookingCommandRouter</code>、<code>EmakiCookingPlugin</code></td></tr><tr><td>Forge</td><td><code>recipes/</code> 的 <code>materials[]</code> 与 <code>blueprint_requirements[]</code> 旧 <code>item_sources</code> 结构迁移到当前字段形态；材料目标保留旧键</td><td><code>/emakiforge convert-legacy</code></td><td><code>ForgeCommandRouter</code>、<code>EmakiForgePlugin</code></td></tr><tr><td>Gem</td><td><code>items/*.yml</code> 的旧 <code>match</code> 块</td><td><code>/emakigem convert-legacy</code></td><td><code>GemCommandRouter</code>、<code>EmakiGemPlugin</code></td></tr><tr><td>Level</td><td><code>sources/*.yml</code> 的 <code>result_item_sources</code> → <code>item_sources</code></td><td><code>/emakilevel convert-legacy</code></td><td><code>LevelCommand</code>、<code>EmakiLevelPlugin</code></td></tr><tr><td>Strengthen</td><td><code>recipes/*.yml</code> 的旧 <code>match</code> 块</td><td><code>/emakistrengthen convert-legacy</code></td><td><code>StrengthenCommandRouter</code></td></tr></tbody></table><h2 id="共同安全性质" tabindex="-1">共同安全性质 <a class="header-anchor" href="#共同安全性质" aria-label="Permalink to “共同安全性质”">​</a></h2><p>这些性质是「可以放心删」的依据：</p><ul><li>只从命令入口与加载期扫描告警进入，运行期的判定、加载、锻造/烹饪/镶嵌路径都不调用它；</li><li>不读运行期状态，不写任何 PDC 条目，不碰玩家存档；只读写插件数据目录下的配置文件；</li><li>删掉整包后，除上表列出的位置外，插件其余部分照常编译。</li></ul><h2 id="各模块特有边界" tabindex="-1">各模块特有边界 <a class="header-anchor" href="#各模块特有边界" aria-label="Permalink to “各模块特有边界”">​</a></h2><p>判定位改成 <code>item_sources</code> 与 <code>matcher</code> 同级 AND 之后，转换器的可迁移面已经明显收窄：</p><p><strong>Cooking / Forge / Gem 仍保留配置迁移目标。</strong> Cooking 的转换器处理工具、锅铲、容器、蒸锅加水规则、营养映射以及各类配方输入的旧扁平 matcher 键；发酵桶 <code>inputs[]</code> 迁移会保留旧键，以保持持久化槽位身份的兼容空间。Forge 的转换器处理 <code>materials[]</code> 与 <code>blueprint_requirements[]</code> 的旧来源字段，材料项保留旧键。Gem 的转换器处理开孔器与宝石定义中的旧来源字段；宝石构造底材当前推荐独立使用 <code>base_item_source</code>，旧顶层 <code>item_sources</code> 仍作为构造底材回退读取。</p><p><strong>Level 仍有一项真实转换：</strong> <code>sources/*.yml</code> 的 <code>rules[].result_item_sources</code> → <code>item_sources</code>。</p><p><strong>Gem / Strengthen 的旧 <code>match</code> 块转换仍在，且输出可直接使用。</strong> 两个转换器都不再往 matcher 里写 <code>type: item_source</code>：Gem 把旧 <code>match.item_sources</code> 提升为顶层 <code>item_sources</code>；Strengthen 把旧 <code>match.source_ids</code> 转成锚定正则（形如 <code>^\\Qemakiitem-xxx\\E$</code>）并合并进顶层 <code>source_patterns</code>。转换结果无需手工修正。</p><h2 id="判断迁移是否完成" tabindex="-1">判断迁移是否完成 <a class="header-anchor" href="#判断迁移是否完成" aria-label="Permalink to “判断迁移是否完成”">​</a></h2><p>旧写法<strong>不会静默失效</strong>：Cooking 的旧扁平前缀键与 Gem 的旧顶层 <code>item_sources</code> 都被加载期兼容读取，只是不再是推荐写法。</p><p>Cooking、Forge、Gem、Level 四个模块启动时会扫描残留旧写法并告警（Strengthen 没有这个调用，只能靠 <code>/emakistrengthen convert-legacy</code> 主动预览）。连续若干个版本没有服主再报告该告警，即可认为迁移期结束，按上面的清单整包下线。</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};